"""Differential test: brute force reference vs submission."""
import sys, json, random, subprocess
sys.path.insert(0, '/workspace/scratch')
sys.path.insert(0, '/workspace/submission')
import gen as G
import ref as R
import analyze as A
from fractions import Fraction


def witness_ok(inst, resp, which):
    w = resp[which]
    k = resp['min_faults']
    coms = inst['commodities']; snaps = inst['snapshots']; edges = inst['edges']
    S = len(snaps); C = len(coms); E = len(edges)
    assert len(w['demands']) == S and len(w['links']) == S
    assert len(w['faults']) == len(set(w['faults']))
    faulty = set()
    for s in range(S):
        qrow = w['demands'][s]
        assert len(qrow) == C
        for c in range(C):
            lo, hi = snaps[s][1][c]
            assert type(qrow[c]) is int and lo <= qrow[c] <= hi, 'bound violated'
        loads = R.loads_for(coms, E, qrow)
        assert [str(x) for x in w['links'][s]] == [ '%d/%d' % (v.numerator, v.denominator) for v in loads], ('links mismatch', w['links'][s], loads)
        assert all(loads[e] <= edges[e][3] for e in range(E)), 'capacity'
        # trusted observations
        ing = {}; egr = {}
        for ci, c in enumerate(coms):
            ing[c[1]] = ing.get(c[1], 0) + qrow[ci]
            egr[c[2]] = egr.get(c[2], 0) + qrow[ci]
        metrics = {}
        for ci, c in enumerate(coms):
            metrics[('demand', c[0])] = qrow[ci]
        for ei, e in enumerate(edges):
            metrics[('link', e[0])] = loads[ei]
        for n in inst['nodes']:
            metrics[('ingress', n)] = ing.get(n, 0)
            metrics[('egress', n)] = egr.get(n, 0)
        for (_oid, metric, target, lo, hi, dom) in snaps[s][4]:
            val = metrics[(metric, target)]
            if not (lo <= val <= hi):
                assert dom is not None, 'trusted violated'
                faulty.add(dom)
    assert set(w['faults']) == faulty, ('fault list', w['faults'], faulty)
    assert len(faulty) == k, ('witness not optimal', faulty, k)
    # ranges consistency
    for s in range(S):
        for c in range(C):
            lo, hi = resp['snapshots'][s]['demands'][c]
            assert lo <= w['demands'][s][c] <= hi, 'witness outside reported range'


def run_one(req):
    inst = A._parse_request(req)
    mine = A.analyze(inst, req['id'])
    refres, stats = R.ref_analyze(inst)
    return inst, mine, refres, stats


def compare(req, verbose=False):
    inst = A._parse_request(req)
    mine = A.analyze(inst, req['id'])
    refres, stats = R.ref_analyze(inst)
    problems = []
    if mine['status'] != refres['status']:
        problems.append(('status', mine['status'], refres['status']))
        return problems, mine, refres
    if refres['status'] == 'infeasible':
        return problems, mine, refres
    if mine['min_faults'] != refres['min_faults']:
        problems.append(('min_faults', mine['min_faults'], refres['min_faults']))
    if set(mine['faults']['forced']) != set(refres['faults']['forced']):
        problems.append(('forced', mine['faults']['forced'], refres['faults']['forced']))
    if set(mine['faults']['possible']) != set(refres['faults']['possible']):
        problems.append(('possible', mine['faults']['possible'], refres['faults']['possible']))
    for s in range(len(inst['snapshots'])):
        ms = mine['snapshots'][s]; rs = refres['snapshots'][s]
        if ms['demands'] != rs['demands']:
            problems.append(('demands s%d' % s, ms['demands'], rs['demands']))
        if ms['links'] != rs['links']:
            problems.append(('links s%d' % s, ms['links'], rs['links']))
        if ms['verdict'] != rs['verdict']:
            problems.append(('verdict s%d' % s, ms['verdict'], rs['verdict']))
    # witness checks
    try:
        witness_ok(inst, mine, 'witness')
    except AssertionError as e:
        problems.append(('witness', str(e), mine.get('witness')))
    if mine['status'] == 'ambiguous':
        if mine.get('alternative') is None:
            problems.append(('alternative missing', None, None))
        else:
            try:
                witness_ok(inst, mine, 'alternative')
                if mine['witness']['demands'] == mine['alternative']['demands']:
                    problems.append(('alternative same', None, None))
            except AssertionError as e:
                problems.append(('alternative', str(e), mine.get('alternative')))
    else:
        if mine.get('alternative') is not None:
            problems.append(('alternative should be null', None, None))
    return problems, mine, refres


def main():
    n = int(sys.argv[1]) if len(sys.argv) > 1 else 200
    seed0 = int(sys.argv[2]) if len(sys.argv) > 2 else 0
    style = sys.argv[3] if len(sys.argv) > 3 else 'small'
    fails = 0
    counts = {}
    for i in range(n):
        rng = random.Random(seed0 * 100000 + i)
        req = G.gen(rng, style)
        try:
            inst = A._parse_request(req)
        except A.Invalid:
            continue
        problems, mine, refres = compare(req)
        counts[mine['status']] = counts.get(mine['status'], 0) + 1
        if problems:
            fails += 1
            print('=== FAIL seed', seed0 * 100000 + i, 'id', req['id'])
            for p in problems:
                print('   ', p)
            print(json.dumps(req))
            if fails >= 3:
                break
    print('done', n, 'fails', fails, counts)


if __name__ == '__main__':
    main()
